package com.metascape.epi;

/**
 * Individual Style 2D Java Implementation.
 * 
 * Generated by metaabm system: Jul 7, 2009 9:37:40 PM PDT in project: org.eclipse.amp.amf.examples.ascape  */

public class IndividualStyle2D extends org.ascape.util.vis.DrawFeature {

	public void draw(java.awt.Graphics g, Object object, int width, int height) {
		java.awt.Shape shape = null;
		org.ascape.model.HostCell rootActGroupCell = (org.ascape.model.HostCell) object;
		if (rootActGroupCell.getOccupant() instanceof Individual) {
			Individual rootActGroup = (Individual) rootActGroupCell
					.getOccupant();
			Individual individualRule = rootActGroup;

			if (individualRule.getStatus() == StatusEnum.susceptible) {

				java.awt.Color individualRuleColorBlue = java.awt.Color.BLUE

				;

				g.setColor(individualRuleColorBlue);
				shape = new java.awt.geom.Ellipse2D.Double(0, 0, width - 2,
						height - 2);
				((java.awt.Graphics2D) g).fill(shape);

			}

			if (individualRule.getStatus() == StatusEnum.exposed) {

				java.awt.Color individualRuleColorYellow = java.awt.Color.YELLOW

				;

				g.setColor(individualRuleColorYellow);
				shape = new java.awt.geom.Ellipse2D.Double(0, 0, width - 2,
						height - 2);
				((java.awt.Graphics2D) g).fill(shape);

			}

			if (individualRule.getStatus() == StatusEnum.asymptomInfectious) {

				java.awt.Color individualRuleColorOrange = java.awt.Color.ORANGE

				;

				g.setColor(individualRuleColorOrange);
				shape = new java.awt.geom.Ellipse2D.Double(0, 0, width - 2,
						height - 2);
				((java.awt.Graphics2D) g).fill(shape);

			}

			if (individualRule.getStatus() == StatusEnum.recovered) {

				java.awt.Color individualRuleColorGreen = java.awt.Color.GREEN

				;

				g.setColor(individualRuleColorGreen);
				shape = new java.awt.geom.Ellipse2D.Double(0, 0, width - 2,
						height - 2);
				((java.awt.Graphics2D) g).fill(shape);

			}

			if (individualRule.getStatus() == StatusEnum.dead) {

				java.awt.Color individualRuleColorBlack = java.awt.Color.BLACK

				;

				g.setColor(individualRuleColorBlack);
				shape = new java.awt.geom.Ellipse2D.Double(0, 0, width - 2,
						height - 2);
				((java.awt.Graphics2D) g).fill(shape);

			}

			if (individualRule.getStatus() == StatusEnum.symptomInfectious) {

				java.awt.Color individualRuleColorRed = java.awt.Color.RED

				;

				g.setColor(individualRuleColorRed);
				shape = new java.awt.geom.Ellipse2D.Double(0, 0, width - 2,
						height - 2);
				((java.awt.Graphics2D) g).fill(shape);

			}

		}
	}
}
